(** * Diagnostic codes *)

Lemma wordToNat_err_morph_not_found : wordToNat ERR_MORPH_NOT_FOUND = KAMI_ERR_MORPH_NOT_FOUND.
Proof.
  unfold KAMI_ERR_MORPH_NOT_FOUND. destruct kami_err_morph_not_found_witness as [n E].
  cbn [proj1_sig]. subst n. rewrite <- N_to_nat_wordToN. f_equal; vm_compute; reflexivity.
Qed.

Lemma wordToNat_err_coupling_invalid : wordToNat ERR_COUPLING_INVALID = KAMI_ERR_COUPLING_INVALID.
Proof.
  unfold KAMI_ERR_COUPLING_INVALID. destruct kami_err_coupling_invalid_witness as [n E].
  cbn [proj1_sig]. subst n. rewrite <- N_to_nat_wordToN. f_equal; vm_compute; reflexivity.
