(** * Table projections *)

Lemma hwb_valid_at : forall n (v : type (Vector Bool n)) (i : word n),
  hwb_valid v (wordToNat i) = v i.
Proof.
  intros n v i. unfold hwb_valid.
  rewrite (proj2 (Nat.ltb_lt _ _) (wordToNat_lt_pow2_small n i)).
  rewrite natToWord_wordToNat. reflexivity.
Qed.

Lemma hwb_valid_update : forall n (v : type (Vector Bool n)) (d : word n) (x : bool),
  hwb_valid (n := n) (fun i => if weq i d then x else v i) =
  fun j => if Nat.eqb j (wordToNat d) then x else hwb_valid v j.
Proof.
  intros n v d x. extensionality j. unfold hwb_valid.
  destruct (Nat.ltb j (2 ^ n)) eqn:Hj.
  - apply Nat.ltb_lt in Hj.
    destruct (weq (natToWord n j) d) as [E|N].
    + subst d. rewrite wordToNat_natToWord_idempotent' by exact Hj.
      rewrite Nat.eqb_refl. reflexivity.
    + destruct (Nat.eqb j (wordToNat d)) eqn:Ejd; [|reflexivity].
      apply Nat.eqb_eq in Ejd. subst j. rewrite natToWord_wordToNat in N. contradiction.
  - apply Nat.ltb_ge in Hj.
    destruct (Nat.eqb j (wordToNat d)) eqn:Ejd; [|reflexivity].
    apply Nat.eqb_eq in Ejd. subst j. pose proof (wordToNat_lt_pow2_small n d). lia.
Qed.

Lemma rich_morph_table_at : forall b (i : word MorphTableIdxSz),
  rich_morph_table (hwb_rich b) (wordToNat i) =
  if hw_morph_valid_table b i then
    Some {| morph_entry_source := wordToNat (hw_morph_src_table b i);
            morph_entry_target := wordToNat (hw_morph_dst_table b i);
            morph_entry_coupling_desc := wordToNat (hw_morph_coupling_desc_table b i);
            morph_entry_is_identity := hw_morph_identity_table b i |}
  else None.
Proof.
  intros b i. unfold hwb_rich. cbn [rich_morph_table].
  rewrite hwb_valid_at, !hwb_vector_nat_at, hwb_valid_at. reflexivity.
Qed.

Lemma rich_coupling_desc_table_at : forall b (d : word CouplingDescIdxSz),
  rich_coupling_desc_table (hwb_rich b) (wordToNat d) =
  if hw_coupling_desc_valid_table b d then
    Some {| coupling_desc_base := wordToNat (hw_coupling_desc_base_table b d);
            coupling_desc_count := wordToNat (hw_coupling_desc_count_table b d);
            coupling_desc_label := atom_label (wordToNat (hw_coupling_desc_label_len_table b d)) (wordToNat (hw_coupling_desc_label_table b d)) |}
  else None.
Proof.
  intros b d. unfold hwb_rich. cbn [rich_coupling_desc_table].
  rewrite hwb_valid_at, !hwb_vector_nat_at. reflexivity.
Qed.

(** * Admission invariants of the morph and coupling tables *)

(** Every valid morph slot lies below [morph_next_id]. *)
Definition hwb_morph_valid_below_next (b : HWB) : Prop :=
  forall i, hw_morph_valid_table b i = true -> wordToNat i < wordToNat (hw_morph_next_id b).

(** Every valid morph slot refers to descriptor 0 or to a valid descriptor
    below [coupling_desc_next_id]. *)
Definition hwb_morph_coupling_refs_ok (b : HWB) : Prop :=
  forall i, hw_morph_valid_table b i = true ->
  hw_coupling_ref_ok b (hw_morph_coupling_desc_table b i) = true.

(** Coupling descriptor 0 is the reserved empty descriptor and is never valid. *)
Definition hwb_coupling_desc_zero_invalid (b : HWB) : Prop :=
  hw_coupling_desc_valid_table b (natToWord CouplingDescIdxSz 0) = false.

Lemma morph_live_valid : forall b i, hwb_morph_valid_below_next b ->
  hw_morph_live b i = hw_morph_valid_table b i.
Proof.
  intros b i H. unfold hw_morph_live.
  destruct (wlt_dec _ _) as [L|L]; [reflexivity|].
  destruct (hw_morph_valid_table b i) eqn:Hv; [|reflexivity].
  exfalso. apply L. apply lt_wlt. rewrite wordToNat_zext. exact (H i Hv).
Qed.

Lemma morph_room_of_lt : forall b, wordToNat (hw_morph_next_id b) < 16 -> hw_morph_room b = true.
Proof.
  intros b H. unfold hw_morph_room.
  destruct (wlt_dec _ _) as [_|L]; [reflexivity|].
  exfalso. apply L. apply lt_wlt. exact H.
Qed.

Lemma module_present_eqb : forall b m,
  hw_module_present b m = negb (Nat.eqb (wordToNat (hw_ptTable b m)) 0).
Proof.
  intros b m. unfold hw_module_present.
  destruct (weq _ _) as [E|N].
  - rewrite E. reflexivity.
  - destruct (Nat.eqb_spec (wordToNat (hw_ptTable b m)) 0) as [Z|Z]; [|reflexivity].
    exfalso. apply N. apply wordToNat_inj. rewrite Z. symmetry. apply wordToNat_word0_32.
Qed.

Lemma wordToNat_trunc4_5_small : forall w : word MorphTableNextIdSz,
  wordToNat w < 16 -> wordToNat (split1 4 1 w) = wordToNat w.
Proof.
  intros w H. rewrite (wordToNat_split1 4 1 w). apply Nat.mod_small. exact H.
Qed.

Lemma word64_ptidx : forall w : word PTableIdxSz, word64 (wordToNat w) = wordToNat w.
Proof.
  intro w. apply word64_below_pow2_32.
  eapply Nat.lt_le_trans; [apply wordToNat_bound|]. apply Nat.pow_le_mono_r; unfold PTableIdxSz; lia.
Qed.

Lemma lt16_pow2_32 : forall n, n < 16 -> n < pow2 32.
Proof.
  intros n H. eapply Nat.lt_le_trans; [exact H|].
  change 16 with (2 ^ 4). apply Nat.pow_le_mono_r; lia.
Qed.

Lemma wordToNat_zext6_32 : forall w : word PTableIdxSz, @wordToNat WordSz (zext w 26) = wordToNat w.
Proof. intro w. exact (wordToNat_zext w 26). Qed.

Lemma wordToNat_zext4_32 : forall w : word 4, @wordToNat WordSz (zext w 28) = wordToNat w.
Proof. intro w. exact (wordToNat_zext w 28). Qed.

