Lemma step_rich_delete : forall b (i : word MorphTableIdxSz),
  hw_morph_valid_table (step_next b) = (fun w => if weq w i then false else hw_morph_valid_table b w) ->
  hw_morph_src_table (step_next b) = hw_morph_src_table b ->
  hw_morph_dst_table (step_next b) = hw_morph_dst_table b ->
  hw_morph_coupling_desc_table (step_next b) = hw_morph_coupling_desc_table b ->
  hw_morph_identity_table (step_next b) = hw_morph_identity_table b ->
  hw_morph_next_id (step_next b) = hw_morph_next_id b ->
  hw_coupling_desc_label_table (step_next b) = hw_coupling_desc_label_table b ->
  hw_coupling_desc_label_len_table (step_next b) = hw_coupling_desc_label_len_table b ->
  hwb_rich (step_next b) = rich_state_delete_morph (hwb_rich b) (wordToNat i).
Proof.
  intros b i H1 H2 H3 H4 H5 H6 H7 H8. unfold hwb_rich at 1.
  rewrite H1, H2, H3, H4, H5, H6, H7, H8. rich_keeps.
  unfold rich_state_delete_morph, hwb_rich. cbn [rich_morph_table rich_next_morph_id
    rich_coupling_desc_table rich_next_coupling_desc_id rich_coupling_pair_table
    rich_next_coupling_pair_id rich_formula_desc_table rich_next_formula_desc_id
    rich_cert_desc_table rich_next_cert_desc_id rich_desc_meta_table
    rich_next_desc_meta_id rich_lassert_state].
  rewrite hwb_valid_update. f_equal.
  extensionality j. destruct (Nat.eqb j (wordToNat i)); reflexivity.
Qed.

Lemma step_rich_alloc : forall b (s : word MorphTableIdxSz) (src dst : word PTableIdxSz)
    (cd : word DescIdxSz) (idf : bool) srcn dstn cdn,
  wordToNat (hw_morph_next_id b) < 16 ->
  wordToNat s = wordToNat (hw_morph_next_id b) ->
  wordToNat src = srcn -> wordToNat dst = dstn -> wordToNat cd = cdn ->
  hw_morph_valid_table (step_next b) = (fun w => if weq w s then true else hw_morph_valid_table b w) ->
  hw_morph_src_table (step_next b) = (fun w => if weq w s then src else hw_morph_src_table b w) ->
  hw_morph_dst_table (step_next b) = (fun w => if weq w s then dst else hw_morph_dst_table b w) ->
  hw_morph_coupling_desc_table (step_next b) =
    (fun w => if weq w s then cd else hw_morph_coupling_desc_table b w) ->
  hw_morph_identity_table (step_next b) = (fun w => if weq w s then idf else hw_morph_identity_table b w) ->
  hw_morph_next_id (step_next b) = wplus (hw_morph_next_id b) (natToWord MorphTableNextIdSz 1) ->
  hw_coupling_desc_label_table (step_next b) = hw_coupling_desc_label_table b ->
  hw_coupling_desc_label_len_table (step_next b) = hw_coupling_desc_label_len_table b ->
  rich_state_add_morph (hwb_rich b) srcn dstn cdn idf =
    (hwb_rich (step_next b), wordToNat (hw_morph_next_id b)).
Proof.
  intros b s src dst cd idf srcn dstn cdn Hroom Hs Hsrc Hdst Hcd H1 H2 H3 H4 H5 H6 H7 H8.
  subst srcn dstn cdn. unfold hwb_rich at 2.
  rewrite H1, H2, H3, H4, H5, H6, H7, H8. rich_keeps.
  unfold rich_state_add_morph, hwb_rich. cbn [rich_morph_table rich_next_morph_id
    rich_coupling_desc_table rich_next_coupling_desc_id rich_coupling_pair_table
    rich_next_coupling_pair_id rich_formula_desc_table rich_next_formula_desc_id
    rich_cert_desc_table rich_next_cert_desc_id rich_desc_meta_table
    rich_next_desc_meta_id rich_lassert_state].
  rewrite !hwb_valid_update, !hwb_vector_nat_update, Hs.
  rewrite (wordToNat_wplus_one_bounded MorphTableNextIdSz) by (cbn; lia).
  f_equal. f_equal; [|lia].
  extensionality j. destruct (Nat.eqb j (wordToNat (hw_morph_next_id b))); reflexivity.
Qed.

