Lemma rich_coupling_desc_table_at4 : forall b (d : word DescIdxSz),
  rich_coupling_desc_table (hwb_rich b) (wordToNat d) =
  if hw_coupling_desc_valid_table b d then
    Some {| coupling_desc_base := wordToNat (hw_coupling_desc_base_table b d);
            coupling_desc_count := wordToNat (hw_coupling_desc_count_table b d);
            coupling_desc_label := atom_label (wordToNat (hw_coupling_desc_label_len_table b d)) (wordToNat (hw_coupling_desc_label_table b d)) |}
  else None.
Proof. intros b d. exact (rich_coupling_desc_table_at b d). Qed.


Lemma get_value_sel0 : forall b i, hw_morph_get_value b i (bits2 false false) = zext (hw_morph_src_table b i) 26.
Proof. reflexivity. Qed.
Lemma get_value_sel1 : forall b i, hw_morph_get_value b i (bits2 true false) = zext (hw_morph_dst_table b i) 26.
Proof. reflexivity. Qed.
Lemma get_value_sel2 : forall b i, hw_morph_get_value b i (bits2 false true) =
  zext (if weq (hw_morph_coupling_desc_table b i) (natToWord DescIdxSz 0)
        then natToWord CouplingPairCountSz 0
        else hw_coupling_desc_count_table b (hw_morph_coupling_desc_table b i)) 27.
Proof. reflexivity. Qed.
Lemma get_value_sel3 : forall b i, hw_morph_get_value b i (bits2 true true) =
  if hw_morph_identity_table b i then natToWord WordSz 1 else natToWord WordSz 0.
Proof. reflexivity. Qed.

Lemma morph_get_value_nat : forall b (i : word MorphTableIdxSz) e0 e1,
  hwb_coupling_desc_zero_invalid b ->
  hw_coupling_ref_ok b (hw_morph_coupling_desc_table b i) = true ->
  wordToNat (hw_morph_get_value b i (bits2 e0 e1)) =
  word64 (match wordToNat (bits2 e0 e1) with
          | 0 => wordToNat (hw_morph_src_table b i)
          | 1 => wordToNat (hw_morph_dst_table b i)
          | 2 => match rich_coupling_desc_table (hwb_rich b)
                         (wordToNat (hw_morph_coupling_desc_table b i)) with
                 | Some desc => coupling_desc_count desc
                 | None => 0
                 end
          | 3 => if hw_morph_identity_table b i then 1 else 0
          | _ => 0
          end).
Proof.
  intros b i e0 e1 Hz Href.
  destruct e0, e1.
  - rewrite get_value_sel3. change (wordToNat (bits2 true true)) with 3. cbv beta iota.
    destruct (hw_morph_identity_table b i); vm_compute; reflexivity.
  - rewrite get_value_sel1. change (wordToNat (bits2 true false)) with 1. cbv beta iota.
    etransitivity; [apply wordToNat_zext6_32|]. symmetry. apply word64_ptidx.
  - rewrite get_value_sel2. change (wordToNat (bits2 false true)) with 2. cbv beta iota.
    rewrite rich_coupling_desc_table_at4.
    unfold hw_coupling_ref_ok in Href. unfold hwb_coupling_desc_zero_invalid in Hz.
    etransitivity; [exact (wordToNat_zext _ 27)|].
    destruct (weq (hw_morph_coupling_desc_table b i) (natToWord DescIdxSz 0)) as [E|E].
    + rewrite E. change (natToWord CouplingDescIdxSz 0) with (natToWord DescIdxSz 0) in Hz.
      rewrite Hz. vm_compute. reflexivity.
    + destruct (wlt_dec _ _) as [_|_]; [|discriminate Href].
      rewrite Href. cbn [coupling_desc_count].
      symmetry. apply word64_below_pow2_32.
      eapply Nat.lt_le_trans; [apply wordToNat_bound|]. apply Nat.pow_le_mono_r; unfold CouplingPairCountSz; lia.
  - rewrite get_value_sel0. change (wordToNat (bits2 false false)) with 0. cbv beta iota.
    etransitivity; [apply wordToNat_zext6_32|]. symmetry. apply word64_ptidx.
Qed.

Theorem step_morph_delete_refines : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 (b : HWB) ,
  step_fetched b = morph_delete_word a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 ->
  hwb_bianchi b = false -> hw_err b = false -> hw_halted b = false ->
  wordToNat (hw_pc b) + 1 < pow2 WordSz ->
  wordToNat (hw_mu b) + wordToNat (bits8 c0 c1 c2 c3 c4 c5 c6 c7) < pow2 WordSz ->
  hwb_morph_valid_below_next b ->
  hwb_snapshot (step_next b) = kami_step (hwb_snapshot b) (instr_morph_delete (wordToNat (bits4 a0 a1 a2 a3)) (wordToNat (bits8 c0 c1 c2 c3 c4 c5 c6 c7))).
